MerfinPlus.TBCBossPlanAssetCatalog = {
  schemaVersion = 1,
  catalogVersion = 1,
  version = 1,
  expansion = "tbc",
  assets = assets,
  assetsByID = assetsByID,
}

function MerfinPlus:GetTBCBossPlanAssetCatalog()
  return self.TBCBossPlanAssetCatalog
end

function MerfinPlus:GetTBCBossPlanAsset(assetID)
  return assetsByID[tostring(assetID or "")]
end

function MerfinPlus:ValidateTBCBossPlanAssetReference(assetID, expectedKind)
  local asset = self:GetTBCBossPlanAsset(assetID)
  if not asset then
    return nil, "Unknown TBC boss-plan asset ID: " .. tostring(assetID or "")
  end
  if expectedKind and asset.kind ~= expectedKind then
    return nil, "Boss-plan asset " .. asset.id .. " is not a " .. tostring(expectedKind) .. " asset."
  end
  return asset
end
